className="report-dialog" aria-labelledby="report-title" onBackdropMouseDown={(event) => {
      if (event.target === event.currentTarget && !submitting) onClose()
    }}

onSelect={(emoji) => {
                      onReact(message, emoji)
                      setReactionPickerMessageId(null)
                    }}
                    onClose={() => setReactionPickerMessageId(null)}

type="search" name="updatesSearch" autoComplete="off" value={query} onChange={(event) => setQuery(event.target.value)} onKeyDown={(event) => {
        if (event.key === 'Enter') void loadUpdates()
      }} placeholder="Search updates…" aria-label="Search updates"

ref={fileInput}
              type="file"
              className="visually-hidden"
              accept="image/gif,image/jpeg,image/png,image/webp,video/mp4,video/webm,.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.zip,.txt,.csv"
              onChange={(event) => {
                const selected = event.currentTarget.files?.[0]
                if (selected) void uploadSpaceFile(selected)
              }}

type={object.payload.multiSelect ? 'checkbox' : 'radio'} name={`poll-${object.id}`} checked={checked}
              disabled={isClosed}
              onChange={() => setSelectedOptions((current) => object.payload.multiSelect
                ? checked ? current.filter((id) => id !== option.id) : [...current, option.id]
                : [option.id])}

ref={avatarInput}
                  className="visually-hidden"
                  type="file"
                  accept="image/jpeg,image/png,image/webp"
                  aria-label="Choose a profile photo"
                  onChange={(event) => selectAvatar(event.currentTarget.files?.[0])}

autoFocus value={query} onChange={(event) => {
            const value = event.target.value
            setQuery(value)
            if (value.trim().length < 2) {
              setSearching(false)
              setError('')
            } else {
              setSearching(true)
              setError('')
            }
          }} placeholder="People, chats, or messages" aria-label="Search people, chats, and loaded messages"

type="file" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.ms-powerpoint,application/vnd.openxmlformats-officedocument.presentationml.presentation,application/zip,text/plain"
            disabled={uploading || attachments.length >= 10}
            onChange={(event) => { const file = event.currentTarget.files?.[0]; if (file) props.onUpload(file); event.currentTarget.value = '' }}

className="voice-scrubber"
              type="range"
              min="0"
              max={Math.max(voiceDuration, 0)}
              step=".05"
              value={Math.max(0, Math.min(voiceCurrent, voiceDuration || 0))}
              disabled={!voiceReady}
              aria-label="Voice note position"
              onChange={(event) => {
                const audio = audioRef.current;
                if (!audio) return;
                audio.currentTime = Number(event.currentTarget.value);
                setVoiceCurrent(audio.currentTime);
              }}

autoFocus
            value={query}
            onChange={(event) => onQueryChange(event.target.value)}
            placeholder="Search loaded messages on this device"
            aria-label="Search messages in this conversation"

id="chat-details-invite"
                value={username}
                onChange={(event) => { setUsername(event.target.value); setSelected(null); setMatches([]); setSearching(false); setError('') }}
                placeholder="Search usernames…"
                maxLength={24}
                autoComplete="off"
                disabled={members.length >= 32 || busy}

ref={textareaRef} rows={1} aria-label="Message" placeholder={`Message ${chatTitle}`} value={draft} maxLength={32000}
        onChange={(event) => { props.onDraftChange(event.target.value); props.onTypingChange(event.target.value) }}
        onBlur={() => props.onTypingChange('')}
        onKeyDown={(event) => { if (event.key === 'Enter' && !event.shiftKey) { event.preventDefault(); event.currentTarget.form?.requestSubmit() } }}

value={appearance} onChange={(event) => {
            const preference = event.currentTarget.value
            try {
              if (preference === 'system' || preference === 'light' || preference === 'dark') {
                onAppearanceChange(preference)
              }
              setError('')
            } catch (appearanceError) {
              setError(appearanceError instanceof Error ? appearanceError.message : 'Unable to save appearance preference.')
            }
          }}

type={object.payload.multiSelect ? 'checkbox' : 'radio'} name={`poll-${object.id}`} checked={checked}
              disabled={isClosed}
              onChange={() => setSelectedOptions((current) => object.payload.multiSelect
                ? checked ? current.filter((id) => id !== option.id) : [...current, option.id]
                : [option.id])}

key={rsvp} type="button" aria-pressed={object.my_response?.rsvp === rsvp} className={object.my_response?.rsvp === rsvp ? 'is-selected' : ''}
          disabled={['cancelled', 'ended'].includes(object.state)}
          onClick={() => onRespond(object, { type: 'event', rsvp })}

type="button"
            onClick={() => {
              if (error && !voiceReady) {
                setError("");
                setVoiceUrl("");
                setVoiceAttempt((v) => v + 1);
                return;
              }
              void toggleVoice();
            }}
            disabled={pending || voiceLoading || (!voiceReady && !error)}
            aria-label={
              error && !voiceReady
                ? "Retry voice note"
                : voicePlaying
                  ? "Pause voice note"
                  : "Play voice note"
            }

